messages.content:
نقش سازمانی: مدیر ایمنی، بهداشت و محیط زیست (hse_manager)

درخواست کاربر:
LTIFR این ماه نسبت به ماه قبل 71٪ افزایش داشته. چه اتفاقی افتاده؟ (مدیر HSE — معدن مس دره‌زار)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "safety_incidents",
      "description": "گزارش حوادث و تقریباً حوادث (near-miss) به تفکیک نوع و شیفت",
      "dimensions": [
        "incident_type",
        "shift",
        "period"
      ],
      "measures": [
        "count",
        "lost_days"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ltifr",
      "description": "نرخ بروز حوادث منجر به غیبت",
      "formula": "(تعداد حوادث منجر به غیبت × ۱٬۰۰۰٬۰۰۰) / کل ساعات کار",
      "unit": "در میلیون ساعت",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با کارخانهٔ فرآوری و منطقهٔ انباشت باطله",
    "محدودیت‌های زیست‌محیطی شامل سقف انتشار و برداشت آب",
    "برنامهٔ احیای اراضی تا پایان دورهٔ بهره‌برداری الزامی است"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "ltifr"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ],
    "comparison": "month_over_month"
  }
}

TOOL_OBSERVATION:
{
  "ltifr": {
    "prev_month": 1.99,
    "curr_month": 3.4,
    "change_pct": 71
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "safety_incidents",
    "filters": {
      "period": "this_month"
    }
  }
}

TOOL_OBSERVATION:
{
  "incidents": [
    {
      "type": "سقوط از ارتفاع",
      "count": 2,
      "shift": "شیفت شب",
      "lost_days": 12
    },
    {
      "type": "برخورد تجهیزات",
      "count": 1,
      "shift": "شیفت صبح",
      "lost_days": 8
    }
  ],
  "total_lti": 3,
  "root_note": "دو مورد سقوط از ارتفاع در شیفت شب (ساعت ۲ تا ۵ صبح) با نور کم و خستگی"
}

نقش سازمانی: مدیر ایمنی، بهداشت و محیط زیست (hse_manager)

درخواست کاربر:
وضعیت احیای اراضی چطور است و آیا به برنامه رسیده‌ایم؟ (مدیر HSE — معدن زغال‌سنگ کرمان)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "rehabilitation",
      "description": "وضعیت احیای اراضی تخریب‌شده",
      "dimensions": [
        "area",
        "period"
      ],
      "measures": [
        "disturbed_ha",
        "rehabilitated_ha",
        "target_ha"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "rehabilitation_rate",
      "description": "نرخ احیای اراضی",
      "formula": "مساحت احیاشده / مساحت تخریب‌شده",
      "unit": "درصد",
      "dimensions": [
        "area"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با کارخانهٔ فرآوری و منطقهٔ انباشت باطله",
    "محدودیت‌های زیست‌محیطی شامل سقف انتشار و برداشت آب",
    "برنامهٔ احیای اراضی تا پایان دورهٔ بهره‌برداری الزامی است"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "rehabilitation",
    "filters": {
      "period": "this_year"
    }
  }
}

نقش سازمانی: مدیر ایمنی، بهداشت و محیط زیست (hse_manager)

درخواست کاربر:
انتشار گازهای گلخانه‌ای تیر یک‌باره جهش کرد و بعد برگشت. چه رخدادی بود و آیا تکرار می‌شود؟ (مدیر HSE — معدن زغال‌سنگ کرمان)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "emissions",
      "description": "انتشار گازهای گلخانه‌ای و آلاینده‌ها",
      "dimensions": [
        "source",
        "period"
      ],
      "measures": [
        "tons_co2",
        "kg_nox",
        "kg_so2"
      ]
    },
    {
      "dataset": "environmental_monitoring",
      "description": "پایش محیط زیست: انتشار، مصرف آب، پسماند",
      "dimensions": [
        "parameter",
        "station",
        "period"
      ],
      "measures": [
        "value",
        "limit",
        "unit"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ghg_intensity",
      "description": "شدت انتشار گازهای گلخانه‌ای",
      "formula": "انتشار کل CO2e / تن محصول",
      "unit": "کیلوگرم CO2e بر تن",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با کارخانهٔ فرآوری و منطقهٔ انباشت باطله",
    "محدودیت‌های زیست‌محیطی شامل سقف انتشار و برداشت آب",
    "برنامهٔ احیای اراضی تا پایان دورهٔ بهره‌برداری الزامی است"
  ]
}

TOOL_CALL:
{
  "tool": "get_timeseries",
  "arguments": {
    "metric": "ghg_intensity",
    "granularity": "month",
    "range": "last_6_months"
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "emissions",
    "filters": {
      "period": "تیر"
    }
  }
}

TOOL_OBSERVATION:
{
  "spike_source": "آتش‌سوزی باطلهٔ سولفیدی در منطقهٔ انباشت — ۳ روز انتشار SO2 بالا",
  "co2_spike_tons": 150,
  "note": "بعد از مهار آتش، انتشار به حالت عادی برگشت"
}

