LTIFR این ماه نسبت به ماه قبل 99٪ افزایش داشته. چه اتفاقی افتاده؟ (مدیر HSE — معدن مس دره‌زار)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "safety_incidents",
      "description": "گزارش حوادث و تقریباً حوادث (near-miss) به تفکیک نوع و شیفت",
      "dimensions": [
        "incident_type",
        "shift",
        "period"
      ],
      "measures": [
        "count",
        "lost_days"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ltifr",
      "description": "نرخ بروز حوادث منجر به غیبت",
      "formula": "(تعداد حوادث منجر به غیبت × ۱٬۰۰۰٬۰۰۰) / کل ساعات کار",
      "unit": "در میلیون ساعت",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با کارخانهٔ فرآوری و منطقهٔ انباشت باطله",
    "محدودیت‌های زیست‌محیطی شامل سقف انتشار و برداشت آب",
    "برنامهٔ احیای اراضی تا پایان دورهٔ بهره‌برداری الزامی است"
  ]
}

TOOL_CALL:
{
  "tool": "get_metric",
  "arguments": {
    "metrics": [
      "ltifr"
    ],
    "period": [
      "prev_month",
      "curr_month"
    ],
    "comparison": "month_over_month"
  }
}

TOOL_OBSERVATION:
{
  "ltifr": {
    "prev_month": 1.55,
    "curr_month": 3.09,
    "change_pct": 99
  }
}

