انتشار گازهای گلخانه‌ای مرداد یک‌باره جهش کرد و بعد برگشت. چه رخدادی بود و آیا تکرار می‌شود؟ (مدیر HSE — معدن سنگ‌آهن سنگان)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "emissions",
      "description": "انتشار گازهای گلخانه‌ای و آلاینده‌ها",
      "dimensions": [
        "source",
        "period"
      ],
      "measures": [
        "tons_co2",
        "kg_nox",
        "kg_so2"
      ]
    },
    {
      "dataset": "environmental_monitoring",
      "description": "پایش محیط زیست: انتشار، مصرف آب، پسماند",
      "dimensions": [
        "parameter",
        "station",
        "period"
      ],
      "measures": [
        "value",
        "limit",
        "unit"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ghg_intensity",
      "description": "شدت انتشار گازهای گلخانه‌ای",
      "formula": "انتشار کل CO2e / تن محصول",
      "unit": "کیلوگرم CO2e بر تن",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با کارخانهٔ فرآوری و منطقهٔ انباشت باطله",
    "محدودیت‌های زیست‌محیطی شامل سقف انتشار و برداشت آب",
    "برنامهٔ احیای اراضی تا پایان دورهٔ بهره‌برداری الزامی است"
  ]
}

TOOL_CALL:
{
  "tool": "get_timeseries",
  "arguments": {
    "metric": "ghg_intensity",
    "granularity": "month",
    "range": "last_6_months"
  }
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "emissions",
    "filters": {
      "period": "مرداد"
    }
  }
}

TOOL_OBSERVATION:
{
  "spike_source": "آتش‌سوزی باطلهٔ سولفیدی در منطقهٔ انباشت — ۳ روز انتشار SO2 بالا",
  "co2_spike_tons": 230,
  "note": "بعد از مهار آتش، انتشار به حالت عادی برگشت"
}

نقش سازمانی: مدیر ایمنی، بهداشت و محیط زیست (hse_manager)

درخواست کاربر:
گزارش ایمنی این ماه را بده: چند حادثه، چند نزدیک حادثه، و شاخص‌های کلیدی چقدر هستند؟ (مدیر HSE — معدن زغال‌سنگ کرمان)

زمینهٔ موجود:
{
  "data_catalog": [
    {
      "dataset": "safety_incidents",
      "description": "گزارش حوادث و تقریباً حوادث (near-miss) به تفکیک نوع و شیفت",
      "dimensions": [
        "incident_type",
        "shift",
        "period"
      ],
      "measures": [
        "count",
        "lost_days"
      ]
    }
  ],
  "metric_catalog": [
    {
      "metric": "ltifr",
      "description": "نرخ بروز حوادث منجر به غیبت",
      "formula": "(تعداد حوادث منجر به غیبت × ۱٬۰۰۰٬۰۰۰) / کل ساعات کار",
      "unit": "در میلیون ساعت",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "trifr",
      "description": "نرخ بروز حوادث قابل ثبت",
      "formula": "(تعداد حوادث قابل ثبت × ۱٬۰۰۰٬۰۰۰) / کل ساعات کار",
      "unit": "در میلیون ساعت",
      "dimensions": [
        "period"
      ]
    },
    {
      "metric": "near_miss_rate",
      "description": "نرخ گزارش تقریباً حوادث",
      "formula": "تعداد near-miss / کل ساعات کار",
      "unit": "در میلیون ساعت",
      "dimensions": [
        "period"
      ]
    }
  ],
  "business_context": [
    "معدن روباز با کارخانهٔ فرآوری و منطقهٔ انباشت باطله",
    "محدودیت‌های زیست‌محیطی شامل سقف انتشار و برداشت آب",
    "برنامهٔ احیای اراضی تا پایان دورهٔ بهره‌برداری الزامی است"
  ]
}

TOOL_CALL:
{
  "tool": "get_dataset",
  "arguments": {
    "name": "safety_incidents",
    "filters": {
      "period": "this_month"
    }
  }
}

